"""A very small SFNT (TrueType/OpenType) reader.

Only what a layout engine needs: family/subfamily names, style bits, vertical
metrics and character coverage.  Written against the spec directly so the
package keeps zero compiled dependencies and stays fast enough to index a few
hundred system fonts.
"""
from __future__ import annotations

import struct
from dataclasses import dataclass, field
from typing import Optional

MAC_PLATFORM = 1
WIN_PLATFORM = 3


@dataclass
class FontInfo:
    path: str
    index: int = 0
    family: str = ''
    subfamily: str = ''
    typo_family: str = ''       # name id 16, the "preferred family"
    typo_subfamily: str = ''    # name id 17
    full_name: str = ''
    ps_name: str = ''
    bold: bool = False
    italic: bool = False
    units_per_em: int = 1000
    ascent: float = 0.8         # fractions of the em (hhea)
    descent: float = 0.2        # positive, fractions of the em (hhea)
    line_gap: float = 0.0
    win_ascent: float = 0.9
    win_descent: float = 0.25
    cff: bool = False
    cap_height: float = 0.7
    x_height: float = 0.5
    italic_angle: float = 0.0
    fixed_pitch: bool = False
    _cmap: Optional[set] = field(default=None, repr=False, compare=False)

    @property
    def line_height(self) -> float:
        return self.ascent + self.descent + self.line_gap

    @property
    def key(self):
        return (self.family.lower(), self.bold, self.italic)

    def covers(self, ch: str) -> bool:
        cmap = self.cmap()
        if not cmap:
            return True
        return ord(ch) in cmap

    def cmap(self):
        if self._cmap is None:
            try:
                self._cmap = read_cmap(self.path, self.index)
            except Exception:
                self._cmap = set()
        return self._cmap


def _decode_name(data: bytes, platform: int, encoding: int) -> str:
    try:
        if platform == WIN_PLATFORM or (platform == 0):
            return data.decode('utf-16-be', 'ignore')
        if platform == MAC_PLATFORM and encoding == 0:
            return data.decode('mac-roman', 'ignore')
        return data.decode('utf-8', 'ignore')
    except Exception:
        return ''


def _table_directory(fh, offset=0):
    fh.seek(offset)
    header = fh.read(12)
    if len(header) < 12:
        raise ValueError('truncated font')
    tag, num_tables = struct.unpack('>4sH', header[:6])
    if tag == b'ttcf':
        raise ValueError('collection header passed to _table_directory')
    tables = {}
    raw = fh.read(16 * num_tables)
    for i in range(num_tables):
        entry = raw[16 * i:16 * i + 16]
        if len(entry) < 16:
            break
        name, _checksum, off, length = struct.unpack('>4sLLL', entry)
        tables[name] = (off, length)
    return tag, tables


def collection_offsets(fh):
    """Offsets of each font inside a .ttc, or ``[0]`` for a plain font file."""
    fh.seek(0)
    header = fh.read(12)
    if header[:4] == b'ttcf':
        count = struct.unpack('>L', header[8:12])[0]
        raw = fh.read(4 * count)
        return list(struct.unpack('>%dL' % count, raw))
    return [0]


def _read_table(fh, tables, tag):
    entry = tables.get(tag)
    if entry is None:
        return None
    off, length = entry
    fh.seek(off)
    return fh.read(length)


def read_font(path: str, index: int = 0) -> Optional[FontInfo]:
    """Read metadata for one font (``index`` selects a face inside a .ttc)."""
    with open(path, 'rb') as fh:
        offsets = collection_offsets(fh)
        if index >= len(offsets):
            return None
        sfnt_tag, tables = _table_directory(fh, offsets[index])
        if sfnt_tag not in (b'\x00\x01\x00\x00', b'true', b'ttcf', b'OTTO'):
            return None
        info = FontInfo(path=path, index=index)
        info.cff = sfnt_tag == b'OTTO'

        head = _read_table(fh, tables, b'head')
        mac_style = 0
        if head and len(head) >= 54:
            info.units_per_em = struct.unpack('>H', head[18:20])[0] or 1000
            mac_style = struct.unpack('>H', head[44:46])[0]

        upem = float(info.units_per_em)
        hhea = _read_table(fh, tables, b'hhea')
        if hhea and len(hhea) >= 36:
            ascent, descent, line_gap = struct.unpack('>hhh', hhea[4:10])
            info.ascent = ascent / upem
            info.descent = -descent / upem
            info.line_gap = line_gap / upem

        os2 = _read_table(fh, tables, b'OS/2')
        if os2 and len(os2) >= 78:
            fs_selection = struct.unpack('>H', os2[62:64])[0]
            win_ascent, win_descent = struct.unpack('>Hh', os2[74:78])
            # Word lays lines out from the hhea metrics; the OS/2 win metrics
            # only stand in when hhea is unusable, and bound highlight boxes.
            info.win_ascent = win_ascent / upem if win_ascent else info.ascent
            info.win_descent = abs(win_descent) / upem if win_descent else info.descent
            if not hhea:
                info.ascent = info.win_ascent
                info.descent = info.win_descent
            info.bold = bool(fs_selection & 0x20)
            info.italic = bool(fs_selection & 0x01)
            if len(os2) >= 90:
                x_height, cap_height = struct.unpack('>hh', os2[86:90])
                if x_height:
                    info.x_height = x_height / upem
                if cap_height:
                    info.cap_height = cap_height / upem
            info.fixed_pitch = os2[35] != 0 if len(os2) > 35 else False
        else:
            info.bold = bool(mac_style & 0x01)
            info.italic = bool(mac_style & 0x02)

        post = _read_table(fh, tables, b'post')
        if post and len(post) >= 16:
            angle = struct.unpack('>l', post[4:8])[0] / 65536.0
            info.italic_angle = angle
            if not info.italic and angle < -0.5:
                info.italic = True

        name = _read_table(fh, tables, b'name')
        if name:
            _apply_names(info, name)
        if mac_style & 0x01:
            info.bold = True
        if mac_style & 0x02:
            info.italic = True
        sub = (info.typo_subfamily or info.subfamily or '').lower()
        if 'bold' in sub:
            info.bold = True
        if 'italic' in sub or 'oblique' in sub:
            info.italic = True
        if sub in ('regular', 'roman', 'book', 'normal'):
            info.bold = info.bold and 'bold' in sub
        if info.typo_family:
            info.family = info.typo_family
        if not info.family:
            info.family = info.full_name or info.ps_name
        return info if info.family else None


def _apply_names(info: FontInfo, data: bytes):
    if len(data) < 6:
        return
    fmt, count, string_offset = struct.unpack('>HHH', data[:6])
    best = {}
    for i in range(count):
        rec = data[6 + 12 * i: 18 + 12 * i]
        if len(rec) < 12:
            break
        platform, encoding, language, name_id, length, offset = struct.unpack('>HHHHHH', rec)
        if name_id not in (1, 2, 4, 6, 16, 17):
            continue
        start = string_offset + offset
        raw = data[start:start + length]
        if not raw:
            continue
        text = _decode_name(raw, platform, encoding).strip('\x00').strip()
        if not text:
            continue
        # prefer Windows/English entries
        score = 2 if platform == WIN_PLATFORM else 1
        if language in (0, 0x409):
            score += 1
        if best.get(name_id, (0, ''))[0] < score:
            best[name_id] = (score, text)
    info.family = best.get(1, (0, ''))[1]
    info.subfamily = best.get(2, (0, ''))[1]
    info.full_name = best.get(4, (0, ''))[1]
    info.ps_name = best.get(6, (0, ''))[1]
    info.typo_family = best.get(16, (0, ''))[1]
    info.typo_subfamily = best.get(17, (0, ''))[1]


def read_cmap(path: str, index: int = 0) -> set:
    """Set of Unicode code points the font can render."""
    out: set = set()
    with open(path, 'rb') as fh:
        offsets = collection_offsets(fh)
        if index >= len(offsets):
            return out
        _tag, tables = _table_directory(fh, offsets[index])
        data = _read_table(fh, tables, b'cmap')
    if not data or len(data) < 4:
        return out
    count = struct.unpack('>H', data[2:4])[0]
    best = None
    best_score = -1
    for i in range(count):
        rec = data[4 + 8 * i:12 + 8 * i]
        if len(rec) < 8:
            break
        platform, encoding, offset = struct.unpack('>HHL', rec)
        score = -1
        if platform == 3 and encoding == 10:
            score = 5
        elif platform == 3 and encoding == 1:
            score = 4
        elif platform == 0:
            score = 3
        elif platform == 3 and encoding == 0:
            score = 2      # symbol encoding
        elif platform == 1 and encoding == 0:
            score = 1
        if score > best_score:
            best_score = score
            best = (platform, encoding, offset)
    if best is None:
        return out
    platform, encoding, offset = best
    symbol = (platform == 3 and encoding == 0)
    if offset + 4 > len(data):
        return out
    fmt = struct.unpack('>H', data[offset:offset + 2])[0]
    if fmt == 4:
        seg_x2 = struct.unpack('>H', data[offset + 6:offset + 8])[0]
        segs = seg_x2 // 2
        base = offset + 14
        ends = struct.unpack('>%dH' % segs, data[base:base + seg_x2])
        starts_at = base + seg_x2 + 2
        starts = struct.unpack('>%dH' % segs, data[starts_at:starts_at + seg_x2])
        deltas_at = starts_at + seg_x2
        deltas = struct.unpack('>%dh' % segs, data[deltas_at:deltas_at + seg_x2])
        ranges_at = deltas_at + seg_x2
        range_offsets = struct.unpack('>%dH' % segs, data[ranges_at:ranges_at + seg_x2])
        for i in range(segs):
            start, end = starts[i], ends[i]
            if start == 0xFFFF:
                continue
            if end - start > 0x4000 and range_offsets[i] == 0:
                # huge delta-mapped range: record it wholesale
                out.update(range(start, end + 1))
                continue
            for code in range(start, min(end, 0xFFFE) + 1):
                if range_offsets[i] == 0:
                    glyph = (code + deltas[i]) & 0xFFFF
                else:
                    gi = ranges_at + i * 2 + range_offsets[i] + (code - start) * 2
                    if gi + 2 > len(data):
                        continue
                    glyph = struct.unpack('>H', data[gi:gi + 2])[0]
                    if glyph:
                        glyph = (glyph + deltas[i]) & 0xFFFF
                if glyph:
                    out.add(code)
    elif fmt == 12:
        n_groups = struct.unpack('>L', data[offset + 12:offset + 16])[0]
        base = offset + 16
        for i in range(min(n_groups, 20000)):
            rec = data[base + 12 * i:base + 12 * i + 12]
            if len(rec) < 12:
                break
            start, end, _gid = struct.unpack('>LLL', rec)
            if end - start > 0x10000:
                end = start + 0x10000
            out.update(range(start, end + 1))
    elif fmt == 6:
        first, count6 = struct.unpack('>HH', data[offset + 6:offset + 10])
        out.update(range(first, first + count6))
    elif fmt == 0:
        for code in range(256):
            gid = data[offset + 6 + code]
            if gid:
                out.add(code)
    if symbol:
        # Symbol fonts map their glyphs into the F0xx private use area; also
        # expose the low byte so plain ASCII lookups succeed.
        out.update(code & 0xFF for code in list(out) if 0xF000 <= code <= 0xF0FF)
    return out
